{"output":""""Tests for theme detection and loading."""

from unittest.mock import patch

from kris_ui.styles.theme_manager import (
    ThemeName,
    get_stylesheet,
    get_system_theme,
    load_stylesheet,
)


class TestGetSystemTheme:
    """Tests for get_system_theme function."""

    @patch("kris_ui.styles.theme_manager.darkdetect.isDark")
    def test_returns_dark_when_system_is_dark(self, mock_is_dark: object) -> None:
        """Test detection of dark system theme."""
        mock_is_dark.return_value = True  # type: ignore[union-attr]
        result = get_system_theme()
        assert result == "dark"

    @patch("kris_ui.styles.theme_manager.darkdetect.isDark")
    def test_returns_light_when_system_is_light(self, mock_is_dark: object) -> None:
        """Test detection of light system theme."""
        mock_is_dark.return_value = False  # type: ignore[union-attr]
        result = get_system_theme()
        assert result == "light"

    @patch("kris_ui.styles.theme_manager.darkdetect.isDark")
    def test_fallback_to_light_when_detection_fails(
        self, mock_is_dark: object
    ) -> None:
        """Test fallback to light when detection raises exception."""
        mock_is_dark.side_effect = Exception("Detection failed")  # type: ignore[union-attr]
        result = get_system_theme()
        assert result == "light"

    @patch("kris_ui.styles.theme_manager.darkdetect.isDark")
    def test_fallback_to_light_when_detection_returns_none(
        self, mock_is_dark: object
    ) -> None:
        """Test fallback to light when detection returns None."""
        mock_is_dark.return_value = None  # type: ignore[union-attr]
        result = get_system_theme()
        assert result == "light"


class TestLoadStylesheet:
    """Tests for load_stylesheet function."""

    def test_load_light_stylesheet_returns_content(self) -> None:
        """Test loading light theme QSS returns non-empty content."""
        qss = load_stylesheet("light")
        assert qss != ""
        assert len(qss) > 0

    def test_load_dark_stylesheet_returns_content(self) -> None:
        """Test loading dark theme QSS returns non-empty content."""
        qss = load_stylesheet("dark")
        assert qss != ""
        assert len(qss) > 0

    def test_light_stylesheet_contains_background_color(self) -> None:
        """Test light theme QSS contains background-color property."""
        qss = load_stylesheet("light")
        assert "background-color" in qss

    def test_dark_stylesheet_contains_background_color(self) -> None:
        """Test dark theme QSS contains background-color property."""
        qss = load_stylesheet("dark")
        assert "background-color" in qss

    def test_light_stylesheet_contains_light_background(self) -> None:
        """Test light theme QSS uses light background color."""
        qss = load_stylesheet("light")
        # Light background: #FAFAFA
        assert "#FAFAFA" in qss or "#fafafa" in qss.lower()

    def test_dark_stylesheet_contains_dark_background(self) -> None:
        """Test dark theme QSS uses dark background color."""
        qss = load_stylesheet("dark")
        # Dark background: #1F1F1F
        assert "#1F1F1F" in qss or "#1f1f1f" in qss.lower()

    def test_load_nonexistent_theme_returns_empty_string(self) -> None:
        """Test loading non-existent theme returns empty string."""
        # Type ignore because we're intentionally passing invalid value
        qss = load_stylesheet("nonexistent")  # type: ignore[arg-type]
        assert qss == ""


class TestGetStylesheet:
    """Tests for get_stylesheet function."""

    @patch("kris_ui.styles.theme_manager.get_system_theme")
    @patch("kris_ui.styles.theme_manager.load_stylesheet")
    def test_calls_get_system_theme(
        self, mock_load: object, mock_theme: object
    ) -> None:
        """Test get_stylesheet calls get_system_theme."""
        mock_theme.return_value = "dark"  # type: ignore[union-attr]
        mock_load.return_value = "/* styles */"  # type: ignore[union-attr]

        get_stylesheet()

        mock_theme.assert_called_once()  # type: ignore[union-attr]

    @patch("kris_ui.styles.theme_manager.get_system_theme")
    @patch("kris_ui.styles.theme_manager.load_stylesheet")
    def test_calls_load_stylesheet_with_detected_theme(
        self, mock_load: object, mock_theme: object
    ) -> None:
        """Test get_stylesheet passes detected theme to load_stylesheet."""
        mock_theme.return_value = "dark"  # type: ignore[union-attr]
        mock_load.return_value = "/* dark styles */"  # type: ignore[union-attr]

        get_stylesheet()

        mock_load.assert_called_once_with("dark")  # type: ignore[union-attr]

    @patch("kris_ui.styles.theme_manager.get_system_theme")
    @patch("kris_ui.styles.theme_manager.load_stylesheet")
    def test_returns_stylesheet_content(
        self, mock_load: object, mock_theme: object
    ) -> None:
        """Test get_stylesheet returns the loaded stylesheet content."""
        mock_theme.return_value = "light"  # type: ignore[union-attr]
        mock_load.return_value = "/* light styles */"  # type: ignore[union-attr]

        result = get_stylesheet()

        assert result == "/* light styles */"

    def test_integration_returns_valid_stylesheet(self) -> None:
        """Integration test: get_stylesheet returns valid QSS content."""
        qss = get_stylesheet()

        # Should return non-empty content
        assert qss != ""
        # Should contain CSS-like content
        assert "background-color" in qss


class TestThemeName:
    """Tests for ThemeName type."""

    def test_light_is_valid_theme_name(self) -> None:
        """Verify 'light' is a valid theme name."""
        theme: ThemeName = "light"
        assert theme == "light"

    def test_dark_is_valid_theme_name(self) -> None:
        """Verify 'dark' is a valid theme name."""
        theme: ThemeName = "dark"
        assert theme == "dark"


class TestStylesheetContent:
    """Tests for stylesheet content quality."""

    def test_light_stylesheet_has_qmainwindow_styles(self) -> None:
        """Test light theme styles QMainWindow."""
        qss = load_stylesheet("light")
        assert "QMainWindow" in qss

    def test_dark_stylesheet_has_qmainwindow_styles(self) -> None:
        """Test dark theme styles QMainWindow."""
        qss = load_stylesheet("dark")
        assert "QMainWindow" in qss

    def test_light_stylesheet_has_button_styles(self) -> None:
        """Test light theme styles QPushButton."""
        qss = load_stylesheet("light")
        assert "QPushButton" in qss

    def test_dark_stylesheet_has_button_styles(self) -> None:
        """Test dark theme styles QPushButton."""
        qss = load_stylesheet("dark")
        assert "QPushButton" in qss

    def test_light_stylesheet_has_input_styles(self) -> None:
        """Test light theme styles QLineEdit."""
        qss = load_stylesheet("light")
        assert "QLineEdit" in qss

    def test_dark_stylesheet_has_input_styles(self) -> None:
        """Test dark theme styles QLineEdit."""
        qss = load_stylesheet("dark")
        assert "QLineEdit" in qss

    def test_stylesheets_have_different_backgrounds(self) -> None:
        """Test light and dark stylesheets use different background colors."""
        light_qss = load_stylesheet("light")
        dark_qss = load_stylesheet("dark")

        # Light uses #FAFAFA, dark uses #1F1F1F
        assert "#FAFAFA" in light_qss
        assert "#1F1F1F" in dark_qss
